// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/shipping/address-lookup", wrapper.LookupAddress)
	router.GET(options.BaseURL+"/shipping/delivery-price-estimate", wrapper.GetDeliveryPriceEstimate)
	router.POST(options.BaseURL+"/shipping/myparcel/connect", wrapper.ConnectMyParcel)
	router.POST(options.BaseURL+"/shipping/connections/:connectionId/register-webhook", wrapper.RegisterMyParcelWebhook)
	router.GET(options.BaseURL+"/shipping/connections/:connectionId/settings", wrapper.GetShippingSettings)
	router.PUT(options.BaseURL+"/shipping/connections/:connectionId/settings", wrapper.UpdateShippingSettings)
	router.PUT(options.BaseURL+"/shipping/connections/:connectionId/carrier-overrides/:carrier", wrapper.UpsertCarrierOverride)
	router.POST(options.BaseURL+"/shipping/shipments", wrapper.CreateShipment)
	router.POST(options.BaseURL+"/shipping/connections/:connectionId/sales-orders/:salesOrderId/export-order", wrapper.ExportMyParcelOrder)
	router.GET(options.BaseURL+"/shipping/sales-orders/:salesOrderId/shipments", wrapper.ListShipmentsForOrder)
	router.GET(options.BaseURL+"/shipping/shipments/:shipmentId/tracking-events", wrapper.ListShipmentTrackingEvents)
	router.POST(options.BaseURL+"/shipping/shipments/:shipmentId/tracking-events/refresh", wrapper.RefreshShipmentTracking)
	router.POST(options.BaseURL+"/shipping/shipments/:shipmentId/cancel", wrapper.CancelShipment)
	router.GET(options.BaseURL+"/shipping/shipments/:shipmentId/label", wrapper.GetShipmentLabel)
}

